import React, { useState, useEffect, useRef, useCallback } from 'react';
import CHAINS from '../chains';
import wattLogo from '../assets/WattLogo.png';
import './ConnectWindow.css';

function ConnectWindow({ connectToChain, closeWindow, walletAddress, logout, currentChain }) {
  const [selIdx, setSelIdx]         = useState(0);
  const [hlIdx,  setHlIdx]          = useState(0);
  const [open,   setOpen]           = useState(false);
  const [pos,    setPos]            = useState(() => ({
    x: Math.max(0, window.innerWidth  / 2 - 190),
    y: Math.max(0, window.innerHeight / 2 - 280),
  }));
  const [dragging, setDragging]     = useState(false);
  const dragOffset                  = useRef({ x: 0, y: 0 });
  const ddRef                       = useRef(null);
  const chain                       = CHAINS[selIdx];

  /* ── keyboard navigation ── */
  useEffect(() => {
    const onKey = (e) => {
      if (!open) {
        if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
          setHlIdx(selIdx);
          setOpen(true);
        }
        return;
      }
      if (e.key === 'ArrowDown')  { e.preventDefault(); setHlIdx(i => (i + 1) % CHAINS.length); }
      else if (e.key === 'ArrowUp')   { e.preventDefault(); setHlIdx(i => (i - 1 + CHAINS.length) % CHAINS.length); }
      else if (e.key === 'Enter')     { setSelIdx(hlIdx); setOpen(false); }
      else if (e.key === 'Escape')    { setOpen(false); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [open, hlIdx, selIdx]);

  /* ── close dropdown on outside click ── */
  useEffect(() => {
    const onOut = (e) => {
      if (ddRef.current && !ddRef.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener('mousedown', onOut);
    return () => document.removeEventListener('mousedown', onOut);
  }, []);

  /* ── drag ── */
  const onTitleMouseDown = useCallback((e) => {
    e.preventDefault();
    dragOffset.current = { x: e.clientX - pos.x, y: e.clientY - pos.y };
    setDragging(true);
  }, [pos]);

  useEffect(() => {
    const move = (e) => {
      setPos({ x: e.clientX - dragOffset.current.x, y: e.clientY - dragOffset.current.y });
    };
    const up = () => setDragging(false);
    if (dragging) {
      window.addEventListener('mousemove', move);
      window.addEventListener('mouseup', up);
    }
    return () => {
      window.removeEventListener('mousemove', move);
      window.removeEventListener('mouseup', up);
    };
  }, [dragging]);

  const handleLogin = () => connectToChain(chain.id, chain);
  const short = (a) => a ? `${a.slice(0, 6)}…${a.slice(-4)}` : '';

  return (
    <div className="cw-dim">
      <div className="cw-win" style={{ left: pos.x, top: pos.y }}>

        {/* ── title bar ── */}
        <div className="cw-bar" onMouseDown={onTitleMouseDown}>
          <img src={wattLogo} alt="" className="cw-bar-logo" />
          <span className="cw-bar-title">Mining Game OS &nbsp;·&nbsp; Login</span>
          <button className="cw-bar-close" onClick={closeWindow} title="Close">✕</button>
        </div>

        <div className="cw-body">
          {walletAddress ? (
            /* ── connected state ── */
            <>
              <div className="cw-avatar">
                <img src={chain.logo} alt={chain.name} className="cw-avatar-img" />
              </div>
              <p className="cw-chain-name">{currentChain || chain.name}</p>
              <p className="cw-address">{short(walletAddress)}</p>
              <button className="cw-btn" onClick={closeWindow}>Enter Desktop</button>
              <button className="cw-btn cw-btn-sec" onClick={logout}>Disconnect</button>
            </>
          ) : (
            /* ── login state ── */
            <>
              <p className="cw-hint">Select a chain to continue</p>

              {/* dropdown */}
              <div className="cw-dd" ref={ddRef}>
                <button
                  className="cw-dd-trigger"
                  onClick={() => { setHlIdx(selIdx); setOpen(o => !o); }}
                  aria-haspopup="listbox"
                  aria-expanded={open}
                >
                  <img src={chain.logo} alt="" className="cw-dd-logo" />
                  <span className="cw-dd-name">{chain.name}</span>
                  <span className="cw-dd-arrow">{open ? '▲' : '▼'}</span>
                </button>

                {open && (
                  <ul className="cw-dd-menu" role="listbox">
                    {CHAINS.map((c, i) => (
                      <li
                        key={c.id}
                        role="option"
                        aria-selected={i === selIdx}
                        className={`cw-dd-item${i === hlIdx ? ' cw-dd-hl' : ''}${i === selIdx ? ' cw-dd-selected' : ''}`}
                        onMouseEnter={() => setHlIdx(i)}
                        onClick={() => { setSelIdx(i); setOpen(false); }}
                      >
                        <img src={c.logo} alt="" className="cw-dd-logo" />
                        <span className="cw-dd-name">{c.name}</span>
                        <span className="cw-dd-cid">{parseInt(c.chainId, 16)}</span>
                      </li>
                    ))}
                  </ul>
                )}
              </div>

              {/* avatar */}
              <div className="cw-avatar">
                <img
                  key={chain.id}
                  src={chain.logo}
                  alt={chain.name}
                  className="cw-avatar-img cw-avatar-anim"
                />
              </div>
              <p className="cw-chain-name">{chain.name}</p>
              <p className="cw-chain-id">Chain ID: {parseInt(chain.chainId, 16)}</p>

              <button className="cw-btn" onClick={handleLogin}>
                Connect Wallet &amp; Login
              </button>
              <button className="cw-btn cw-btn-ghost" onClick={closeWindow}>
                Continue without wallet
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

export default ConnectWindow;
