import React, { useState, useEffect } from 'react';
import BootScreen      from './components/BootScreen';
import Taskbar         from './components/Taskbar';
import ConnectWindow   from './components/ConnectWindow';
import StartMenu       from './components/StartMenu';
import AppsPanel       from './components/AppsPanel';
import SettingsPanel   from './components/SettingsPanel';
import BrowserWindow from './components/BrowserWindow';
import DesktopIcon   from './components/DesktopIcon';
import './App.css';
import defaultBg   from './assets/MiningGameBackground.png';
import browserIcon from './assets/browser.png';
import swapinIcon  from './assets/SwapinLogo.png';
import wattIcon    from './assets/WattLogo.png';

function App() {
  // ── boot / login phase ──────────────────────────────────────────────────────
  const [phase,          setPhase]          = useState('boot');
  const [showLogin,      setShowLogin]      = useState(true);

  // ── wallet ──────────────────────────────────────────────────────────────────
  const [walletAddress,  setWalletAddress]  = useState('');
  const [walletConnected,setWalletConnected]= useState(false);
  const [currentChain,   setCurrentChain]   = useState('');
  const [currentChainHex,setCurrentChainHex]= useState('');

  // ── appearance ───────────────────────────────────────────────────────────────
  const [theme,      setThemeState] = useState(() => localStorage.getItem('mgos_theme') || 'dark');
  const [background, setBackground] = useState(defaultBg);

  // Apply theme to document root for CSS variable switching
  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('mgos_theme', theme);
  }, [theme]);

  const setTheme = (t) => setThemeState(t);

  // ── windows ──────────────────────────────────────────────────────────────────
  const [openWindows,      setOpenWindows]      = useState([]);
  const [minimizedWindows, setMinimizedWindows] = useState([]);
  const [browserUrl,       setBrowserUrl]       = useState(null); // URL to open in browser

  // Mapping from app name to URL — opens that URL in the Browser window
  const APP_URLS = {
    'DerpFi':    'https://derpfi.com/',
    'SwapinDEX': 'https://swapin.co',
  };

  // ── panels ───────────────────────────────────────────────────────────────────
  const [appsOpen,     setAppsOpen]     = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [startMenuOpen,setStartMenuOpen]= useState(false);

  // ── wallet connect ───────────────────────────────────────────────────────────
  const connectToChain = async (chainId, chainConfig) => {
    if (!window.ethereum) {
      alert('MetaMask or a compatible wallet is required to connect.\nInstall MetaMask and reload.');
      return;
    }
    try {
      await window.ethereum.request({ method: 'eth_requestAccounts' });
      const accounts = await window.ethereum.request({ method: 'eth_accounts' });
      if (!accounts.length) return;

      await window.ethereum.request({
        method: 'wallet_addEthereumChain',
        params: [{
          chainId:          chainConfig.chainId,
          rpcUrls:          [chainConfig.rpc],
          chainName:        chainConfig.name,
          nativeCurrency:   { name: chainConfig.symbol, symbol: chainConfig.symbol, decimals: chainConfig.decimals },
          blockExplorerUrls:[chainConfig.explorer],
        }],
      });

      setWalletAddress(accounts[0]);
      setWalletConnected(true);
      setCurrentChain(chainConfig.name);
      setCurrentChainHex(chainConfig.chainId);
    } catch (err) {
      console.error('Chain connection error:', err);
    }
  };

  const disconnectWallet = () => {
    setWalletAddress('');
    setWalletConnected(false);
    setCurrentChain('');
    setCurrentChainHex('');
  };

  // ── window management ────────────────────────────────────────────────────────
  const launchApp = (name) => {
    const url = APP_URLS[name];
    if (url) {
      // Open URL-based apps inside the Browser window as a new tab
      setBrowserUrl(url);
      if (!openWindows.includes('Browser')) setOpenWindows(ws => [...ws, 'Browser']);
    } else {
      if (!openWindows.includes(name)) setOpenWindows(ws => [...ws, name]);
    }
    setStartMenuOpen(false);
    setAppsOpen(false);
  };

  const closeApp  = (name) => {
    setOpenWindows(ws => ws.filter(w => w !== name));
    setMinimizedWindows(ms => ms.filter(w => w !== name));
  };

  const minimizeApp = (name) => {
    setOpenWindows(ws => ws.filter(w => w !== name));
    if (!minimizedWindows.includes(name)) setMinimizedWindows(ms => [...ms, name]);
  };

  const restoreApp = (name) => {
    if (!openWindows.includes(name)) setOpenWindows(ws => [...ws, name]);
    setMinimizedWindows(ms => ms.filter(w => w !== name));
  };

  // ── login flow ───────────────────────────────────────────────────────────────
  const closeLogin = () => {
    setShowLogin(false);
    if (phase === 'login') setPhase('desktop');
  };

  // ── start menu ───────────────────────────────────────────────────────────────
  const handleStartMenuApps = () => {
    setStartMenuOpen(false);
    setSettingsOpen(false);
    setAppsOpen(true);
  };

  const handleStartMenuSettings = () => {
    setStartMenuOpen(false);
    setAppsOpen(false);
    setSettingsOpen(true);
  };

  // ── boot ─────────────────────────────────────────────────────────────────────
  if (phase === 'boot') {
    return <BootScreen onBootComplete={() => setPhase('login')} />;
  }

  return (
    <div
      className="app-desktop"
      style={{ backgroundImage: `url(${background})` }}
      onClick={() => setStartMenuOpen(false)}
    >
      {/* Desktop icons */}
      <div className="app-icons">
        {[
          { name: 'Browser',     icon: browserIcon },
          { name: 'SwapinDEX',   icon: swapinIcon  },
          { name: 'Mining Game', icon: wattIcon     },
        ].map(({ name, icon }) => (
          <DesktopIcon key={name} appName={name} icon={icon} openApp={launchApp} />
        ))}
      </div>

      {/* ── App windows ── */}
      {openWindows.includes('Browser') && (
        <BrowserWindow
          minimizeWindow={() => minimizeApp('Browser')}
          closeWindow={() => closeApp('Browser')}
          initialUrl={browserUrl}
        />
      )}

      {/* ── Login dialog ── */}
      {(phase === 'login' || showLogin) && (
        <ConnectWindow
          connectToChain={connectToChain}
          closeWindow={closeLogin}
          walletAddress={walletAddress}
          logout={disconnectWallet}
          currentChain={currentChain}
        />
      )}

      {/* ── Side panels ── */}
      <AppsPanel
        isOpen={appsOpen}
        onClose={() => setAppsOpen(false)}
        launchApp={launchApp}
        walletAddress={walletAddress}
        currentChain={currentChain}
      />

      <SettingsPanel
        isOpen={settingsOpen}
        onClose={() => setSettingsOpen(false)}
        theme={theme}
        setTheme={setTheme}
        background={background}
        setBackground={setBackground}
        walletAddress={walletAddress}
        currentChainHex={currentChainHex}
      />

      {/* ── Start menu ── */}
      {startMenuOpen && (
        <StartMenu
          walletConnected={walletConnected}
          walletAddress={walletAddress}
          handleConnectClick={() => setShowLogin(true)}
          handleDisconnectClick={disconnectWallet}
          launchApp={launchApp}
          onClose={() => setStartMenuOpen(false)}
          onOpenApps={handleStartMenuApps}
          onOpenSettings={handleStartMenuSettings}
        />
      )}

      {/* ── Taskbar ── */}
      <Taskbar
        toggleStartMenu={(e) => { e.stopPropagation(); setStartMenuOpen(o => !o); }}
        openWindows={openWindows}
        minimizedWindows={minimizedWindows}
        restoreWindow={restoreApp}
        restoreConnectWindow={() => setShowLogin(true)}
      />
    </div>
  );
}

export default App;
