import React from 'react';
import Clock from './Clock';
import wattLogo from '../assets/WattLogo.png';
import './Taskbar.css';

const APP_EMOJI = {
  'Browser':       '🌐',
  'SwapinDEX':     '💱',
  'Mining Game':   '⛏️',
  'THA Miner':     '💻',
  'DerpFi':        '🐸',
  'URANUS-DAO':    '🪐',
  'Connect to EVM':'🔗',
};

function Taskbar({ toggleStartMenu, minimizedWindows = [], restoreWindow, restoreConnectWindow, openWindows = [] }) {
  const tabs = [
    ...openWindows.map(w => ({ name: w, active: true })),
    ...minimizedWindows.filter(w => !openWindows.includes(w)).map(w => ({ name: w, active: false })),
  ];

  const handleTab = (tab) => {
    if (tab.name === 'Connect to EVM') restoreConnectWindow?.('Connect to EVM');
    else restoreWindow?.(tab.name);
  };

  return (
    <div className="tb-bar">
      {/* Start button */}
      <button className="tb-start" onClick={toggleStartMenu} title="Applications">
        <img src={wattLogo} alt="Menu" className="tb-start-img" />
      </button>

      <div className="tb-sep" />

      {/* Open-window tabs */}
      <div className="tb-tabs">
        {tabs.map((tab, i) => (
          <button
            key={i}
            className={`tb-tab${tab.active ? ' tb-tab-active' : ' tb-tab-min'}`}
            onClick={() => handleTab(tab)}
            title={tab.name}
          >
            <span className="tb-tab-ico">{APP_EMOJI[tab.name] || '🖥️'}</span>
            <span className="tb-tab-lbl">{tab.name}</span>
          </button>
        ))}
      </div>

      {/* System tray */}
      <div className="tb-tray">
        <span className="tb-tray-dot" title="Network" />
        <Clock />
      </div>
    </div>
  );
}

export default Taskbar;
