/**
 * Personal desktop storage manager.
 * Uses IndexedDB for file blobs (persistent) + localStorage for quota metadata.
 *
 * Free tier:  100 MB
 * Paid tier:  +100 MB per 1 $ (purchased via StorageSubscription smart contract)
 */

const DB_NAME    = 'MiningGameOS_Files';
const DB_VERSION = 1;
const STORE_NAME = 'files';

const FREE_QUOTA_BYTES   = 100 * 1024 * 1024; // 100 MB
const BYTES_PER_UNIT     = 100 * 1024 * 1024; // 100 MB per paid unit

// ── IndexedDB helpers ──────────────────────────────────────────────────────────

function openDB() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = (e) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };
    req.onsuccess = (e) => resolve(e.target.result);
    req.onerror   = (e) => reject(e.target.error);
  });
}

async function idbPut(record) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx    = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const req   = store.put(record);
    req.onsuccess = () => resolve();
    req.onerror   = (e) => reject(e.target.error);
  });
}

async function idbGet(id) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx    = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const req   = store.get(id);
    req.onsuccess = (e) => resolve(e.target.result);
    req.onerror   = (e) => reject(e.target.error);
  });
}

async function idbDelete(id) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx    = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const req   = store.delete(id);
    req.onsuccess = () => resolve();
    req.onerror   = (e) => reject(e.target.error);
  });
}

async function idbGetAll() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx    = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const req   = store.getAll();
    req.onsuccess = (e) => resolve(e.target.result);
    req.onerror   = (e) => reject(e.target.error);
  });
}

// ── Quota metadata (localStorage) ─────────────────────────────────────────────

function getMeta() {
  try {
    return JSON.parse(localStorage.getItem('mgos_quota') || '{}');
  } catch { return {}; }
}

function saveMeta(m) {
  localStorage.setItem('mgos_quota', JSON.stringify(m));
}

// ── Public API ─────────────────────────────────────────────────────────────────

export function getTotalQuota() {
  const m = getMeta();
  return FREE_QUOTA_BYTES + ((m.paidUnits || 0) * BYTES_PER_UNIT);
}

export function getUsedBytes() {
  const m = getMeta();
  return m.usedBytes || 0;
}

export function getAvailableBytes() {
  return getTotalQuota() - getUsedBytes();
}

export function getPaidUnits() {
  return getMeta().paidUnits || 0;
}

/** Called by smart contract callback after successful purchase */
export function recordPurchase(units) {
  const m = getMeta();
  m.paidUnits = (m.paidUnits || 0) + units;
  saveMeta(m);
}

export function hasSpace(bytes) {
  return bytes <= getAvailableBytes();
}

/**
 * Save a sanitized image Blob to the desktop.
 * Returns the stored file record or throws if over quota.
 */
export async function saveFile(name, blob, category = 'documents') {
  if (!hasSpace(blob.size)) {
    throw new Error(`Not enough storage space. Free ${formatBytes(getAvailableBytes())} remaining.`);
  }

  const id     = `${Date.now()}_${Math.random().toString(36).slice(2)}`;
  const record = {
    id,
    name,
    size:     blob.size,
    type:     blob.type,
    category, // 'documents' | 'backgrounds'
    uploadedAt: Date.now(),
    blob,
  };

  await idbPut(record);

  const m       = getMeta();
  m.usedBytes   = (m.usedBytes || 0) + blob.size;
  saveMeta(m);

  return record;
}

export async function deleteFile(id, size) {
  await idbDelete(id);
  const m     = getMeta();
  m.usedBytes = Math.max(0, (m.usedBytes || 0) - size);
  saveMeta(m);
}

export async function getFileBlob(id) {
  const rec = await idbGet(id);
  return rec ? rec.blob : null;
}

export async function listFiles(category = null) {
  const all = await idbGetAll();
  return category ? all.filter(f => f.category === category) : all;
}

export function formatBytes(b) {
  if (b >= 1024 * 1024) return (b / 1024 / 1024).toFixed(1) + ' MB';
  if (b >= 1024)        return (b / 1024).toFixed(1) + ' KB';
  return b + ' B';
}

export const BYTES_PER_PAID_UNIT = BYTES_PER_UNIT;
