import React, { useState, useRef, useEffect } from 'react';
import './StartMenu.css';

/* ─────────────────────────────────────────────────────────────
   App catalogue  – add new entries here, never in JSX
───────────────────────────────────────────────────────────── */
const MENU = [
  {
    label: 'Apps', icon: '📦',
    children: [
      { label: 'Browser',   icon: '🌐', app: 'Browser' },
      {
        label: 'DeFi', icon: '💱',
        children: [
          { label: 'SwapinDEX',   icon: '💱', app: 'SwapinDEX'   },
          { label: 'Mining Game', icon: '⛏️', app: 'Mining Game' },
          { label: 'DerpFi',      icon: '🐸', app: 'DerpFi'      },
          { label: 'URANUS-DAO',  icon: '🪐', app: 'URANUS-DAO'  },
        ],
      },
      {
        label: 'Miners', icon: '⛏️',
        children: [
          { label: 'THA Miner', icon: '💻', app: 'THA Miner' },
        ],
      },
    ],
  },
  {
    label: 'Settings', icon: '⚙️',
    children: [
      { label: 'General', icon: '🛠️' },
      { label: 'Display', icon: '🖥️' },
      { label: 'Sound',   icon: '🔊' },
    ],
  },
];

/* flatten to a single list for search */
function flatApps(items, acc = []) {
  for (const item of items) {
    if (item.app) acc.push(item);
    if (item.children) flatApps(item.children, acc);
  }
  return acc;
}
const ALL_APPS = flatApps(MENU);

/* ── single menu row, supports click-to-expand sub-menus ── */
function Row({ item, launchApp, closeMenu, depth = 0 }) {
  const [exp, setExp] = useState(false);
  const ref = useRef(null);

  const hasChildren = item.children?.length > 0;

  // close on outside click
  useEffect(() => {
    if (!exp) return;
    const h = (e) => { if (ref.current && !ref.current.contains(e.target)) setExp(false); };
    document.addEventListener('mousedown', h);
    return () => document.removeEventListener('mousedown', h);
  }, [exp]);

  const click = () => {
    if (item.app) { launchApp(item.app); closeMenu(); }
    else if (hasChildren) setExp(o => !o);
  };

  return (
    <div className={`sm-row-wrap${depth > 0 ? ' sm-nested' : ''}`} ref={ref}>
      <div className={`sm-row${exp ? ' sm-row-open' : ''}`} onClick={click}>
        <span className="sm-ico">{item.icon}</span>
        <span className="sm-lbl">{item.label}</span>
        {hasChildren && <span className="sm-caret">▶</span>}
      </div>
      {exp && hasChildren && (
        <div className="sm-sub">
          {item.children.map((child, i) => (
            <Row key={i} item={child} launchApp={launchApp} closeMenu={closeMenu} depth={depth + 1} />
          ))}
        </div>
      )}
    </div>
  );
}

/* ── main start menu ── */
function StartMenu({ walletConnected, walletAddress, handleConnectClick, handleDisconnectClick, launchApp, onClose, onOpenApps, onOpenSettings }) {
  const [q, setQ] = useState('');
  const ref = useRef(null);

  // close on outside click
  useEffect(() => {
    const h = (e) => { if (ref.current && !ref.current.contains(e.target)) onClose?.(); };
    document.addEventListener('mousedown', h);
    return () => document.removeEventListener('mousedown', h);
  }, [onClose]);

  const results = q.trim()
    ? ALL_APPS.filter(a => a.label.toLowerCase().includes(q.toLowerCase()))
    : null;

  const shortAddr = walletAddress
    ? `${walletAddress.slice(0, 6)}…${walletAddress.slice(-4)}`
    : null;

  return (
    <div className="sm-root" ref={ref}>

      {/* search */}
      <div className="sm-search-row">
        <span className="sm-search-ico">🔍</span>
        <input
          className="sm-search-inp"
          type="text"
          placeholder="Search apps…"
          value={q}
          onChange={e => setQ(e.target.value)}
          autoFocus
        />
      </div>

      {/* wallet info */}
      <div className="sm-wallet-row">
        <span className={`sm-wallet-dot${walletConnected ? ' sm-wallet-on' : ''}`} />
        <span className="sm-wallet-txt">
          {walletConnected ? shortAddr : 'Not connected'}
        </span>
      </div>

      <hr className="sm-hr" />

      {/* items */}
      <div className="sm-items">
        {results ? (
          results.length > 0
            ? results.map((item, i) => (
                <div key={i} className="sm-row" onClick={() => { launchApp(item.app); onClose?.(); }}>
                  <span className="sm-ico">{item.icon}</span>
                  <span className="sm-lbl">{item.label}</span>
                </div>
              ))
            : <p className="sm-empty">No results for "{q}"</p>
        ) : (
          <>
            {/* Apps — opens the full AppsPanel side drawer */}
            <div className="sm-row" onClick={onOpenApps}>
              <span className="sm-ico">📦</span>
              <span className="sm-lbl">Apps</span>
              <span className="sm-caret">▶</span>
            </div>

            {/* Settings — opens the SettingsPanel side drawer */}
            <div className="sm-row" onClick={onOpenSettings}>
              <span className="sm-ico">⚙️</span>
              <span className="sm-lbl">Settings</span>
              <span className="sm-caret">▶</span>
            </div>

            {/* Remaining items that stay inline */}
            {MENU.filter(m => m.label !== 'Apps' && m.label !== 'Settings').map((item, i) => (
              <Row key={i} item={item} launchApp={launchApp} closeMenu={onClose} />
            ))}
          </>
        )}
      </div>

      <hr className="sm-hr" />

      {/* bottom actions */}
      <div className="sm-foot">
        {walletConnected ? (
          <button className="sm-foot-btn" onClick={() => { handleDisconnectClick(); onClose?.(); }}>
            🔌&nbsp; Disconnect Wallet
          </button>
        ) : (
          <button className="sm-foot-btn" onClick={() => { handleConnectClick(); onClose?.(); }}>
            🔗&nbsp; Connect Wallet
          </button>
        )}
      </div>
    </div>
  );
}

export default StartMenu;
