import React, { useState, useRef, useEffect } from 'react';
import { ethers } from 'ethers';
import bg from '../assets/MiningGameBackground.png';
import './SettingsPanel.css';
import {
  getTotalQuota, getUsedBytes, getAvailableBytes,
  saveFile, formatBytes, recordPurchase,
} from '../utils/storageManager';
import { scanAndSanitize, MAX_FILE_SIZE } from '../utils/fileScanner';

const STORAGE_ABI = [
  'function purchaseStorage(uint256 units) payable',
  'function getStorageMB(address user) view returns (uint256)',
  'function pricePerUnit() view returns (uint256)',
];
const CONTRACT_ADDRESSES = {
  '0x921': '', // WATTxchain 2337 — fill after deployment
  '0x91A': '', // Altcoinchain 2330 — fill after deployment
  '0x89':  '', // Polygon 137 — fill after deployment
};
const PRICE_PER_UNIT_FALLBACK = ethers.parseEther('0.001');

const PRESETS = [{ label: 'Mining Game', url: bg }];

function StorageBar({ used, total }) {
  const pct = total > 0 ? Math.min(100, (used / total) * 100) : 0;
  const color = pct > 85 ? '#e74c3c' : pct > 60 ? '#f0a040' : '#4caf50';
  return (
    <div className="sp-bar-wrap">
      <div className="sp-bar-track">
        <div className="sp-bar-fill" style={{ width: `${pct}%`, background: color }} />
      </div>
      <div className="sp-bar-labels">
        <span>{formatBytes(used)} used</span>
        <span>{formatBytes(total)} total</span>
      </div>
    </div>
  );
}

function SettingsPanel({ isOpen, onClose, theme, setTheme, background, setBackground, walletAddress, currentChainHex }) {
  const [scanMsg,      setScanMsg]      = useState('');
  const [scanStatus,   setScanStatus]   = useState('idle'); // idle|scanning|ok|warn|error
  const [buying,       setBuying]       = useState(false);
  const [buyUnits,     setBuyUnits]     = useState(1);
  const [buyStatus,    setBuyStatus]    = useState('');
  const [storageSnap,  setStorageSnap]  = useState({ used: getUsedBytes(), total: getTotalQuota() });
  const fileRef = useRef(null);
  const panelRef = useRef(null);

  // Refresh storage numbers when panel opens
  useEffect(() => {
    if (isOpen) setStorageSnap({ used: getUsedBytes(), total: getTotalQuota() });
  }, [isOpen]);

  // Close on outside click
  useEffect(() => {
    if (!isOpen) return;
    const h = (e) => { if (panelRef.current && !panelRef.current.contains(e.target)) onClose(); };
    document.addEventListener('mousedown', h);
    return () => document.removeEventListener('mousedown', h);
  }, [isOpen, onClose]);

  // ── file upload handler ──────────────────────────────────────────────────────
  const handleFileChange = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    e.target.value = '';

    if (file.size > MAX_FILE_SIZE) {
      setScanStatus('error');
      setScanMsg(`File too large (${formatBytes(file.size)}). Max 10 MB per file.`);
      return;
    }
    if (file.size > getAvailableBytes()) {
      setScanStatus('error');
      setScanMsg(`Not enough storage space. ${formatBytes(getAvailableBytes())} available.`);
      return;
    }

    setScanStatus('scanning');
    setScanMsg('Scanning file for malware and malicious code…');

    try {
      const { safe, sanitizedBlob, threats, details } = await scanAndSanitize(file);

      if (!safe) {
        setScanStatus('error');
        setScanMsg(`❌ File rejected:\n${details}`);
        return;
      }

      if (threats.length > 0) {
        setScanStatus('warn');
        setScanMsg(`⚠️ Suspicious patterns found and removed during sanitization:\n${details}`);
      } else {
        setScanStatus('ok');
        setScanMsg('✅ ' + details);
      }

      // Save sanitized blob to IndexedDB
      await saveFile(file.name, sanitizedBlob, 'backgrounds');

      // Set as background
      const url = URL.createObjectURL(sanitizedBlob);
      setBackground(url);

      setStorageSnap({ used: getUsedBytes(), total: getTotalQuota() });
    } catch (err) {
      setScanStatus('error');
      setScanMsg(`Scan error: ${err.message}`);
    }
  };

  // ── smart contract purchase ──────────────────────────────────────────────────
  const handleBuyStorage = async () => {
    if (!walletAddress) { setBuyStatus('Connect a wallet first.'); return; }
    const contractAddr = CONTRACT_ADDRESSES[currentChainHex] || '';
    if (!contractAddr) {
      setBuyStatus('Storage contract not yet deployed on this chain. Check back soon.');
      return;
    }

    setBuying(true);
    setBuyStatus('Waiting for wallet…');
    try {
      const provider = new ethers.BrowserProvider(window.ethereum);
      const signer   = await provider.getSigner();
      const contract = new ethers.Contract(contractAddr, STORAGE_ABI, signer);

      let unitPrice;
      try { unitPrice = await contract.pricePerUnit(); }
      catch { unitPrice = PRICE_PER_UNIT_FALLBACK; }

      const value = unitPrice * ethers.toBigInt(buyUnits);
      const tx    = await contract.purchaseStorage(buyUnits, { value });
      setBuyStatus('Transaction submitted. Waiting for confirmation…');
      await tx.wait();

      recordPurchase(buyUnits);
      setStorageSnap({ used: getUsedBytes(), total: getTotalQuota() });
      setBuyStatus(`✅ +${buyUnits * 100} MB added to your account!`);
    } catch (err) {
      setBuyStatus(`Transaction failed: ${err.message?.slice(0, 120)}`);
    } finally {
      setBuying(false);
    }
  };

  const scanStatusClass = { idle: '', scanning: 'sp-scan-scanning', ok: 'sp-scan-ok', warn: 'sp-scan-warn', error: 'sp-scan-error' }[scanStatus];

  return (
    <>
      <div className={`sp-backdrop${isOpen ? ' sp-backdrop-visible' : ''}`} onClick={onClose} />

      <div className={`sp-panel${isOpen ? ' sp-panel-open' : ''}`} ref={panelRef}>
        <div className="sp-header">
          <span className="sp-title">⚙️ Settings</span>
          <button className="sp-close" onClick={onClose}>✕</button>
        </div>

        <div className="sp-scroll">

          {/* ── Appearance ── */}
          <div className="sp-group">
            <p className="sp-group-label">Appearance</p>
            <div className="sp-theme-row">
              <button
                className={`sp-theme-btn${theme === 'dark' ? ' sp-theme-active' : ''}`}
                onClick={() => setTheme('dark')}
              >🌙 Dark</button>
              <button
                className={`sp-theme-btn${theme === 'light' ? ' sp-theme-active' : ''}`}
                onClick={() => setTheme('light')}
              >☀️ Light</button>
            </div>
          </div>

          {/* ── Background ── */}
          <div className="sp-group">
            <p className="sp-group-label">Desktop Background</p>

            {/* Presets */}
            <div className="sp-wallpaper-grid">
              {PRESETS.map(p => (
                <div
                  key={p.label}
                  className={`sp-wallpaper-thumb${background === p.url ? ' sp-wallpaper-active' : ''}`}
                  style={{ backgroundImage: `url(${p.url})` }}
                  onClick={() => setBackground(p.url)}
                  title={p.label}
                />
              ))}
            </div>

            {/* Custom upload */}
            <button className="sp-upload-btn" onClick={() => fileRef.current?.click()}>
              📁 Upload Custom Background
            </button>
            <input
              ref={fileRef}
              type="file"
              accept=".jpg,.jpeg,.png,.avif"
              style={{ display: 'none' }}
              onChange={handleFileChange}
            />
            <p className="sp-upload-hint">Accepted: .jpg .jpeg .png .avif · Max 10 MB per file</p>

            {scanMsg && (
              <pre className={`sp-scan-msg ${scanStatusClass}`}>{scanMsg}</pre>
            )}
          </div>

          {/* ── Storage ── */}
          <div className="sp-group">
            <p className="sp-group-label">Personal Storage</p>
            <StorageBar used={storageSnap.used} total={storageSnap.total} />
            <p className="sp-storage-note">
              100 MB free · {formatBytes(getAvailableBytes())} available
            </p>

            <div className="sp-buy-row">
              <label className="sp-buy-label">Buy more:</label>
              <input
                type="number"
                min="1"
                max="100"
                value={buyUnits}
                onChange={e => setBuyUnits(Math.max(1, parseInt(e.target.value) || 1))}
                className="sp-buy-input"
              />
              <span className="sp-buy-label">× 100 MB</span>
            </div>
            <p className="sp-buy-hint">≈ $1 per 100 MB in native chain token</p>

            <button className="sp-buy-btn" onClick={handleBuyStorage} disabled={buying}>
              {buying ? 'Processing…' : `Buy ${buyUnits * 100} MB`}
            </button>

            {buyStatus && <p className="sp-buy-status">{buyStatus}</p>}
          </div>

        </div>
      </div>
    </>
  );
}

export default SettingsPanel;
