import React, { useState, useEffect, useRef } from 'react';
import './AppsPanel.css';
import browserIcon  from '../assets/browser.png';
import swapinIcon   from '../assets/SwapinLogo.png';
import wattIcon     from '../assets/WattLogo.png';
import altLogo      from '../assets/AltLogo.png';
import { listFiles, deleteFile, getFileBlob, formatBytes } from '../utils/storageManager';

const APP_GRID = [
  { name: 'Browser',     icon: browserIcon, category: 'apps'  },
  { name: 'SwapinDEX',   icon: swapinIcon,  category: 'apps'  },
  { name: 'Mining Game', icon: wattIcon,    category: 'games' },
  { name: 'THA Miner',   icon: wattIcon,    category: 'apps'  },
  { name: 'DerpFi',      icon: altLogo,     category: 'apps'  },
  { name: 'URANUS-DAO',  icon: wattIcon,    category: 'apps'  },
];


function FileRow({ file, onDelete, onOpen }) {
  return (
    <div className="ap-file-row">
      <span className="ap-file-ico">🖼️</span>
      <span className="ap-file-name" title={file.name}>{file.name}</span>
      <span className="ap-file-size">{formatBytes(file.size)}</span>
      <button className="ap-file-btn" onClick={() => onOpen(file)} title="View">👁️</button>
      <button className="ap-file-btn ap-file-del" onClick={() => onDelete(file)} title="Delete">🗑️</button>
    </div>
  );
}

function Section({ title, icon, open, toggle, children }) {
  return (
    <div className="ap-section">
      <div className="ap-section-hd" onClick={toggle}>
        <span>{icon} {title}</span>
        <span className="ap-section-caret">{open ? '▾' : '▸'}</span>
      </div>
      {open && <div className="ap-section-body">{children}</div>}
    </div>
  );
}

function AppsPanel({ isOpen, onClose, launchApp, walletAddress, currentChain }) {
  const [openSections, setOpenSections] = useState({ Apps: true, Documents: false, Downloads: false, Games: false, Wallet: false });
  const [docFiles,     setDocFiles]     = useState([]);
  const [viewUrl,      setViewUrl]      = useState(null);
  const panelRef = useRef(null);

  useEffect(() => {
    if (!isOpen) return;
    listFiles('documents').then(setDocFiles).catch(() => {});
  }, [isOpen]);

  // Close on outside click
  useEffect(() => {
    if (!isOpen) return;
    const h = (e) => { if (panelRef.current && !panelRef.current.contains(e.target)) onClose(); };
    document.addEventListener('mousedown', h);
    return () => document.removeEventListener('mousedown', h);
  }, [isOpen, onClose]);

  const toggle = (sec) => setOpenSections(s => ({ ...s, [sec]: !s[sec] }));

  const handleDelete = async (file) => {
    if (!window.confirm(`Delete "${file.name}"?`)) return;
    await deleteFile(file.id, file.size);
    setDocFiles(fs => fs.filter(f => f.id !== file.id));
  };

  const handleOpen = async (file) => {
    let url = viewUrl;
    if (url) { URL.revokeObjectURL(url); }
    const blob = await getFileBlob(file.id);
    if (blob) { setViewUrl(URL.createObjectURL(blob)); }
  };

  const gamesApps = APP_GRID.filter(a => a.category === 'games');
  const mainApps  = APP_GRID.filter(a => a.category === 'apps');

  return (
    <>
      {/* Backdrop */}
      <div className={`ap-backdrop${isOpen ? ' ap-backdrop-visible' : ''}`} onClick={onClose} />

      {/* Panel */}
      <div className={`ap-panel${isOpen ? ' ap-panel-open' : ''}`} ref={panelRef}>
        <div className="ap-header">
          <span className="ap-title">📁 Desktop</span>
          <button className="ap-close" onClick={onClose}>✕</button>
        </div>

        <div className="ap-scroll">

          {/* ── Apps ── */}
          <Section title="Apps" icon="📦" open={openSections.Apps} toggle={() => toggle('Apps')}>
            <div className="ap-app-grid">
              {mainApps.map(app => (
                <div key={app.name} className="ap-app-tile" onClick={() => { launchApp(app.name); onClose(); }}>
                  <img src={app.icon} alt={app.name} className="ap-app-ico" />
                  <span className="ap-app-lbl">{app.name}</span>
                </div>
              ))}
            </div>
          </Section>

          {/* ── Documents ── */}
          <Section title="Documents" icon="📄" open={openSections.Documents} toggle={() => toggle('Documents')}>
            {docFiles.length === 0 ? (
              <p className="ap-empty">No documents uploaded yet.</p>
            ) : (
              docFiles.map(f => (
                <FileRow key={f.id} file={f} onDelete={handleDelete} onOpen={handleOpen} />
              ))
            )}
          </Section>

          {/* ── Downloads ── */}
          <Section title="Downloads" icon="⬇️" open={openSections.Downloads} toggle={() => toggle('Downloads')}>
            <p className="ap-empty">Download manager coming soon.</p>
          </Section>

          {/* ── Games ── */}
          <Section title="Games" icon="🎮" open={openSections.Games} toggle={() => toggle('Games')}>
            <div className="ap-app-grid">
              {gamesApps.map(app => (
                <div key={app.name} className="ap-app-tile" onClick={() => { launchApp(app.name); onClose(); }}>
                  <img src={app.icon} alt={app.name} className="ap-app-ico" />
                  <span className="ap-app-lbl">{app.name}</span>
                </div>
              ))}
            </div>
          </Section>

          {/* ── Wallet ── */}
          <Section title="Wallet" icon="👛" open={openSections.Wallet} toggle={() => toggle('Wallet')}>
            {walletAddress ? (
              <div className="ap-wallet-info">
                <div className="ap-wallet-row">
                  <span className="ap-wallet-lbl">Chain</span>
                  <span className="ap-wallet-val">{currentChain || '—'}</span>
                </div>
                <div className="ap-wallet-row">
                  <span className="ap-wallet-lbl">Address</span>
                  <span className="ap-wallet-val ap-mono">
                    {walletAddress.slice(0, 8)}…{walletAddress.slice(-6)}
                  </span>
                </div>
                <button className="ap-wallet-copy" onClick={() => navigator.clipboard.writeText(walletAddress)}>
                  📋 Copy Address
                </button>
              </div>
            ) : (
              <p className="ap-empty">Connect a wallet to view info.</p>
            )}
          </Section>

        </div>

        {/* Image viewer mini-modal */}
        {viewUrl && (
          <div className="ap-viewer" onClick={() => setViewUrl(null)}>
            <img src={viewUrl} alt="Preview" className="ap-viewer-img" />
            <p className="ap-viewer-hint">Click to close</p>
          </div>
        )}
      </div>
    </>
  );
}

export default AppsPanel;
