import React, { useEffect, useState } from 'react';
import wattLogo from '../assets/WattLogo.png';
import './BootScreen.css';

function BootScreen({ onBootComplete }) {
  const [progress, setProgress] = useState(0);
  const [fadeOut, setFadeOut]   = useState(false);

  useEffect(() => {
    const id = setInterval(() => {
      setProgress(p => {
        const next = p + 2;
        if (next >= 100) {
          clearInterval(id);
          setFadeOut(true);
          setTimeout(onBootComplete, 650);
          return 100;
        }
        return next;
      });
    }, 50); // 50 steps × 50 ms = 2.5 s
    return () => clearInterval(id);
  }, [onBootComplete]);

  return (
    <div className={`boot-screen${fadeOut ? ' boot-fadeout' : ''}`}>
      <div className="boot-content">
        <img src={wattLogo} alt="Mining Game OS" className="boot-logo" />
        <h1 className="boot-title">Mining Game OS</h1>
        <p className="boot-subtitle">Virtual Boy · Decentralized Resource System</p>
        <div className="boot-bar-track">
          <div className="boot-bar-fill" style={{ width: `${progress}%` }} />
        </div>
        <p className="boot-pct">{progress}%</p>
      </div>
    </div>
  );
}

export default BootScreen;
