/**
 * Client-side image security scanner + sanitizer.
 *
 * Pipeline:
 *  1. Whitelist extension + MIME
 *  2. Verify magic bytes (real file type)
 *  3. Scan binary content for malicious patterns
 *  4. Re-encode through <canvas> — strips ALL metadata, EXIF, embedded files
 *  5. Return sanitized Blob + threat report
 *
 * NOTE: For production, pair with a server-side AV scan (ClamAV / VirusTotal).
 */

// ── allowed types ──────────────────────────────────────────────────────────────
const ALLOWED_EXT  = new Set(['jpg', 'jpeg', 'png', 'avif']);
const ALLOWED_MIME = new Set(['image/jpeg', 'image/png', 'image/avif']);

// ── magic-byte signatures ───────────────────────────────────────────────────────
const MAGIC = [
  { label: 'JPEG',    bytes: [0xFF, 0xD8, 0xFF],                         offset: 0 },
  { label: 'PNG',     bytes: [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A], offset: 0 },
  // AVIF: "ftyp" box at offset 4
  { label: 'AVIF',    bytes: [0x66, 0x74, 0x79, 0x70],                   offset: 4 },
];

// ── threat signatures in binary content ────────────────────────────────────────
const THREATS = [
  { name: 'Windows PE executable',  sig: [0x4D, 0x5A] },                         // MZ
  { name: 'Linux ELF executable',   sig: [0x7F, 0x45, 0x4C, 0x46] },             // ELF
  { name: 'Mach-O executable',      sig: [0xCE, 0xFA, 0xED, 0xFE] },             // Mach-O LE
  { name: 'ZIP/archive embedded',   sig: [0x50, 0x4B, 0x03, 0x04] },             // PK
  { name: 'RAR archive embedded',   sig: [0x52, 0x61, 0x72, 0x21] },             // Rar!
  { name: 'Gzip archive embedded',  sig: [0x1F, 0x8B] },
  { name: 'HTML <script> tag',      sig: strBytes('<script') },
  { name: 'PHP injection',          sig: strBytes('<?php') },
  { name: 'ASP injection',          sig: strBytes('<%@') },
  { name: 'JSP injection',          sig: strBytes('<%=') },
  { name: 'eval() pattern',         sig: strBytes('eval(') },
  { name: 'document.write',         sig: strBytes('document.write') },
  { name: 'window.location hijack', sig: strBytes('window.location') },
  // eslint-disable-next-line no-script-url
  { name: 'javascript: URI',        sig: strBytes('javascript:') },
  // eslint-disable-next-line no-script-url
  { name: 'vbscript: URI',          sig: strBytes('vbscript:') },
  { name: 'Base64 payload marker',  sig: strBytes('base64,') },
  { name: 'data:text/html',         sig: strBytes('data:text/html') },
  { name: 'PowerShell payload',     sig: strBytes('powershell') },
  { name: 'Bash shebang',           sig: strBytes('#!/') },
  { name: 'Shell injection',        sig: strBytes('/bin/sh') },
  // Long null-byte run (common in shellcode padding)
  { name: 'Shellcode NOP sled',     sig: [0x90, 0x90, 0x90, 0x90, 0x90, 0x90, 0x90, 0x90] },
];

function strBytes(s) {
  return Array.from(s).map(c => c.charCodeAt(0));
}

// ── helpers ────────────────────────────────────────────────────────────────────

function matchAt(view, sig, offset) {
  if (offset + sig.length > view.byteLength) return false;
  for (let i = 0; i < sig.length; i++) {
    if (view.getUint8(offset + i) !== sig[i]) return false;
  }
  return true;
}

function scanForSignature(view, sig) {
  const end = view.byteLength - sig.length;
  for (let i = 0; i <= end; i++) {
    if (matchAt(view, sig, i)) return i;
  }
  return -1;
}

function verifyMagic(view) {
  for (const m of MAGIC) {
    if (matchAt(view, m.bytes, m.offset)) return m.label;
  }
  return null;
}

// ── canvas re-encode (strips ALL embedded content) ────────────────────────────

function sanitizeViaCanvas(file, mimeOut = 'image/png') {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width  = img.naturalWidth;
      canvas.height = img.naturalHeight;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0);
      URL.revokeObjectURL(url);
      canvas.toBlob(blob => {
        if (blob) resolve(blob);
        else      reject(new Error('Canvas re-encode failed'));
      }, mimeOut, 0.92);
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error('Image could not be decoded'));
    };
    img.src = url;
  });
}

// ── public API ─────────────────────────────────────────────────────────────────

/**
 * Scan and sanitize an uploaded image file.
 *
 * @param {File} file
 * @returns {Promise<{ safe: boolean, sanitizedBlob: Blob|null, threats: string[], details: string }>}
 */
export async function scanAndSanitize(file) {
  const result = { safe: false, sanitizedBlob: null, threats: [], details: '' };

  // 1. Extension check
  const ext = file.name.split('.').pop().toLowerCase();
  if (!ALLOWED_EXT.has(ext)) {
    result.details = `File extension ".${ext}" is not allowed. Accepted: .jpg .jpeg .png .avif`;
    return result;
  }

  // 2. MIME type check
  if (!ALLOWED_MIME.has(file.type)) {
    result.details = `MIME type "${file.type}" is not allowed.`;
    return result;
  }

  // 3. Read binary
  const buf  = await file.arrayBuffer();
  const view = new DataView(buf);

  // 4. Magic bytes — real file type must match extension
  const detected = verifyMagic(view);
  if (!detected) {
    result.details = 'File header does not match any known image format. Rejected.';
    result.threats.push('Unknown / spoofed file type');
    return result;
  }
  const extOk =
    (detected === 'JPEG' && (ext === 'jpg' || ext === 'jpeg')) ||
    (detected === 'PNG'  && ext === 'png') ||
    (detected === 'AVIF' && ext === 'avif');
  if (!extOk) {
    result.details = `Detected format (${detected}) does not match claimed extension (.${ext}). Possible spoofing.`;
    result.threats.push(`Format mismatch: header=${detected}, ext=.${ext}`);
    return result;
  }

  // 5. Scan for threat signatures
  for (const t of THREATS) {
    const pos = scanForSignature(view, t.sig);
    if (pos !== -1) {
      result.threats.push(`${t.name} (offset 0x${pos.toString(16)})`);
    }
  }

  // 6. Check for content appended after JPEG end marker (FF D9)
  if (detected === 'JPEG') {
    for (let i = view.byteLength - 2; i >= 0; i--) {
      if (view.getUint8(i) === 0xFF && view.getUint8(i + 1) === 0xD9) {
        if (i < view.byteLength - 2) {
          result.threats.push(`Data appended after JPEG end marker at offset 0x${i.toString(16)}`);
        }
        break;
      }
    }
  }

  // 7. Re-encode through canvas regardless — this strips everything suspicious
  try {
    const mimeOut = detected === 'PNG' ? 'image/png' : 'image/jpeg';
    result.sanitizedBlob = await sanitizeViaCanvas(file, mimeOut);
  } catch (e) {
    result.details = `Sanitization failed: ${e.message}`;
    return result;
  }

  result.safe = true;
  if (result.threats.length > 0) {
    result.details = `WARNING: ${result.threats.length} suspicious pattern(s) detected and stripped during sanitization:\n• ${result.threats.join('\n• ')}`;
  } else {
    result.details = 'File passed all security checks and was sanitized successfully.';
  }

  return result;
}

export const MAX_FILE_SIZE_MB = 10; // per-file limit
export const MAX_FILE_SIZE    = MAX_FILE_SIZE_MB * 1024 * 1024;
